// Turns VELORA's scheduler request into an OpenAI call with a strict JSON schema.
const b = $json.body;
const system = [
  'You turn a spa manager\'s free-text request into rota changes. Today is ' + b.today + ' (timezone Europe/Sofia).',
  'Therapists (use their ids in "therapist"): ' + JSON.stringify(b.therapists) + '.',
  'The rota covers ' + b.rotaHorizon?.from + ' to ' + b.rotaHorizon?.to + '. Studio rules: ' + (b.rules ?? []).join(' '),
  'Resolve relative dates ("till 6th January", "next week", "tomorrow") against today; assume the next occurrence of a date if no year is given.',
  '"Sick", "ill", "болен/болна" → SICK; "paid leave", "vacation", "отпуск" → PAID_LEAVE; "unpaid", "неплатен" → UNPAID.',
  '"Extra shifts" without dates means this week (leave from/to null). Do not invent changes the manager did not ask for.',
  'Fields that do not apply to a change type must be null. Dates are YYYY-MM-DD.',
  'If something is ambiguous, return no change for it and ask in "reply". Reply in the manager\'s language, in one or two sentences.',
].join('\n');
const history = (b.history ?? []).slice(0, -1) // the last entry is the current message
  .filter((h) => h.role === 'ADMIN' || h.role === 'AI')
  .map((h) => ({ role: h.role === 'ADMIN' ? 'user' : 'assistant', content: h.content }));
const str = { type: ['string', 'null'] };
return [{ json: { requestBody: {
  model: 'gpt-5-mini',
  messages: [{ role: 'system', content: system }, ...history, { role: 'user', content: b.message }],
  response_format: { type: 'json_schema', json_schema: { name: 'rota_changes', strict: true, schema: {
    type: 'object', additionalProperties: false, required: ['reply', 'changes'],
    properties: {
      reply: { type: 'string' },
      changes: { type: 'array', items: {
        type: 'object', additionalProperties: false,
        required: ['type', 'therapist', 'from', 'to', 'absenceType', 'note', 'count', 'date'],
        properties: {
          type: { type: 'string', enum: ['absence', 'extra_shifts', 'day_off', 'add_shift'] },
          therapist: { type: 'string' },
          from: str, to: str, note: str, date: str,
          absenceType: { type: ['string', 'null'], enum: ['SICK', 'PAID_LEAVE', 'UNPAID', 'OTHER', null] },
          count: { type: ['integer', 'null'] },
        },
      } },
    },
  } } },
} } }];

// Drops null fields (VELORA's schema expects them absent) and never fails the webhook.
try {
  if ($json.error) throw new Error(typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error));
  const out = JSON.parse($json.choices[0].message.content);
  const changes = (out.changes ?? []).map((c) => Object.fromEntries(Object.entries(c).filter(([, v]) => v !== null)));
  return [{ json: { reply: out.reply, changes } }];
} catch (e) {
  return [{ json: { reply: 'The AI could not process that request (' + String(e.message ?? e).slice(0, 120) + '). Please try again or use the manual form.', changes: [] } }];
}
